namespace ghidra.app.util.viewer.field;

using docking.widgets.fieldpanel.field;
using generic.theme.GThemeDefaults.Colors;
using ghidra.app.nav;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;

/**
 * An annotated string handler that is used to display an error message string when there is a
 * problem creating an annotated string.
 */
public class InvalidAnnotatedStringHandler : AnnotatedStringHandler {

	private string errorText;

	public InvalidAnnotatedStringHandler() {
		errorText = "Invalid Annotation";
	}

	public InvalidAnnotatedStringHandler(string errorText) {
		this.errorText = errorText;
	}

	/* @Override */
	public AttributedString createAnnotatedString(AttributedString prototypeString, string[] text,
			Program program)
    {
		return new AttributedString(errorText, Messages.ERROR, prototypeString.getFontMetrics(0));
	}

	/* @Override */
	public string[] getSupportedAnnotations() {
		return new string[0];
	}

	/* @Override */
	public bool handleMouseClick(string[] annotationParts, Navigatable navigatable,
			ServiceProvider serviceProvider) {
		return false; // we don't handle clicks!!!
	}

	/* @Override */
	public string getDisplayString() {
		return "Invalid";
	}

	/* @Override */
	public string getPrototypeString() {
		return "";
	}

	/* @Override */
	public string getPrototypeString(string displayText) {
		return this.getPrototypeString();
	}
}
